    wire a_to_b, b_to_a, b_to_b;
    always @(*) begin
        case (state)
            2'b00: begin a_to_b = 1; b_to_a = 0; b_to_b = 0; end
            2'b01: begin a_to_b = 0; b_to_a = 0; b_to_b = 1; end
            2'b10: begin a_to_b = 0; b_to_a = 1; b_to_b = 0; end
