        case (state)
            2'b00: next_state = (in & a_to_b) ? 2'b01 : (in & b_to_a) ? 2'b10 : (in & b_to_b) ? 2'b00 : 2'b00;
            2'b01: next_state = (in & a_to_b) ? 2'b01 : (in & b_to_a) ? 2'b10 : (in & b_to_b) ? 2'b01 : 2'b01;
